// ============================================================
// LecturerSets — the paper as its lecturers write it
// ============================================================
// One card per lecturer: who they are, the format their part takes, and a
// swipeable row of the title slides they taught from. A tap on a slide opens
// practice on that deck's topics in the lecturer's format; the button under
// the row opens the whole part.
//
// The number on every button comes from a phase-scoped, per-format count
// table generated by the same rule the session applies, so "ถูกผิด 6 ข้อ"
// is what a tap will actually serve. Where a deck has no question in the
// lecturer's format yet, the card says so and offers the mixed set instead of
// opening an empty session.
// ============================================================
import { LECTURER_SETS, LECTURER_SET_SCOPE, FORMAT_LABEL, lecturerTopics } from '../data/lecturer-sets.js';
import { LECTURE_COVERS } from '../data/art.js';
import { Q_COUNTS_BY_TOPIC_BY_KIND_BY_SCOPE } from '../data/q-kind-counts.generated.js';

const TH_MONTH = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
function thaiDate(iso) {
  const [, m, d] = String(iso || '').split('-').map(Number);
  return m ? `${d} ${TH_MONTH[m - 1]}` : '';
}

export default function LecturerSets({ subject, topics = [], onStart, onOpenInstructor, selectedPhase = LECTURER_SET_SCOPE.phase }) {
  const set = LECTURER_SETS[subject];
  if (!set || typeof onStart !== 'function') return null;

  const labelOf = (topicId) => topics.find((t) => t.id === topicId)?.label || topicId;
  const kindTable = Q_COUNTS_BY_TOPIC_BY_KIND_BY_SCOPE[selectedPhase]?.[subject] || {};
  const countOf = (topicIds, kind) => topicIds.reduce((sum, id) => {
    const row = kindTable[id] || {};
    return sum + (kind === 'all' ? Object.values(row).reduce((a, b) => a + b, 0) : (row[kind] || 0));
  }, 0);
  const covers = LECTURE_COVERS[subject] || {};

  return (
    <div className="vmx-lect-list">
      <p className="vmx-lect-intro">
        กลางภาค {thaiDate(set.examDate)} — {set.coverage} แยกตามอาจารย์ผู้สอนและรูปแบบข้อสอบที่แต่ละท่านใช้
      </p>
      {set.lecturers.map((lec) => {
        const all = lecturerTopics(lec);
        const inFormat = countOf(all, lec.format);
        const inAny = countOf(all, 'all');
        const formatLabel = FORMAT_LABEL[lec.format] || lec.format;
        const wholeCategory = inFormat > 0 ? lec.format : 'all';
        const wholeCount = inFormat > 0 ? inFormat : inAny;
        const wholeLabel = inFormat > 0
          ? `ฝึกแบบ${formatLabel}ทุกหัวข้อของอาจารย์ (${wholeCount} ข้อ)`
          : `ยังไม่มีข้อแบบ${formatLabel} ฝึกรวมทุกประเภท (${wholeCount} ข้อ)`;
        return (
          <article key={lec.id} className="vmx-lect" aria-label={lec.name}>
            <header className="vmx-lect-head">
              <button
                type="button"
                className="vmx-lect-name"
                onClick={() => onOpenInstructor?.(lec.lecturer)}
                title="ดูโปรไฟล์อาจารย์"
              >
                {lec.name}
              </button>
              <span className={`vmx-lect-chip${lec.announced ? '' : ' is-unannounced'}`}>
                {formatLabel}{lec.count ? ` ${lec.count} ข้อ` : ''}
              </span>
              <span className="vmx-lect-note">{lec.note}</span>
            </header>

            <div className="vmx-lect-strip" role="list" aria-label={`สไลด์ที่ ${lec.name} สอน`}>
              {lec.sessions.map((s) => s.decks.map((deck) => {
                const art = covers[deck.cover];
                const title = deck.title || labelOf(deck.topics[0]);
                const n = countOf(deck.topics, lec.format);
                const nAll = countOf(deck.topics, 'all');
                const usable = n > 0 ? lec.format : 'all';
                const shown = n > 0 ? n : nAll;
                const countText = n > 0
                  ? `${formatLabel} ${n} ข้อ`
                  : (nAll > 0 ? `ยังไม่มีข้อแบบ${formatLabel} (รวม ${nAll} ข้อ)` : 'ยังไม่มีข้อสอบ');
                return (
                  <button
                    key={`${s.n}-${deck.cover}`}
                    type="button"
                    role="listitem"
                    className="vmx-lect-cover"
                    disabled={shown === 0}
                    aria-label={`${title} คาบ ${s.n} ${thaiDate(s.date)}, ${countText}`}
                    onClick={() => onStart({ subjectId: subject, topics: deck.topics, questionCategory: usable })}
                  >
                    {art ? <img src={art.src} alt={art.alt} loading="lazy" decoding="async" /> : <span className="vmx-lect-cover-blank" aria-hidden="true" />}
                    <span className="t">{title}</span>
                    <span className="c">{countText}</span>
                    <span className="s">คาบ {s.n} ({thaiDate(s.date)})</span>
                  </button>
                );
              }))}
            </div>

            <div className="vmx-lect-actions">
              <button
                type="button"
                className="vmx-lect-btn is-primary"
                disabled={wholeCount === 0}
                onClick={() => onStart({ subjectId: subject, topics: all, questionCategory: wholeCategory })}
              >
                {wholeLabel}
              </button>
              {lec.count && inFormat >= lec.count && (
                <button
                  type="button"
                  className="vmx-lect-btn"
                  onClick={() => onStart({ subjectId: subject, topics: all, questionCategory: lec.format, numQuestions: lec.count })}
                >
                  จำลองชุด {lec.count} ข้อ
                </button>
              )}
            </div>
          </article>
        );
      })}
    </div>
  );
}
